<?php
declare(strict_types=1);
namespace app\cms\template;

/** Capability boundary for PHP generated by the frontend template compiler. */
final class CompiledTemplatePolicy
{
    private const TAGS = ['tagad','tagadv','tagarcclick','tagarclist','tagarcpagelist','tagarcview','tagarticlepay','tagasklist','tagattr','tagattribute','tagchannel','tagchannelartlist','tagcitysite','tagcollect','tagcollectnum','tagcomment','tagdiyfield','tagdiyurl','tagdowncount','tagdownloadpay','tagfaq','tagfield','tagflink','tagformreply','tagfreebuynum','tagglobal','tagguestbookform','taghotwords','taglang','taglanguage','taglikearticle','taglist','tagload','tagmemberinfos','tagmemberlist','tagnavigation','tagnotice','tagpagelist','tagpagespecnode','tagposition','tagprenext','tagscreening','tagsearchform','tagsearchurl','tagspaddress','tagspcart','tagspecnode','tagspecnodelist','tagsporder','tagsporderlist','tagsppayapilist','tagsppurchase','tagspsearch','tagspsubmitorder','tagsql','tagstatic','tagtag','tagtagarclist','tagtype','taguser','tagusermenu','tagvideolist','tagvideoplay'];

    public static function validate(string $compiled): void
    {
        try { $nodes = (new \PhpParser\ParserFactory())->createForHostVersion()->parse($compiled); }
        catch (\Throwable $e) { throw new \InvalidArgumentException('编译后的模板语法无效', 0, $e); }
        foreach ($nodes ?? [] as $node) self::visit($node);
    }

    private static function visit(\PhpParser\Node $node, ?\PhpParser\Node $parent = null): void
    {
        $allowed = [
            'Stmt_InlineHTML','Stmt_Echo','Stmt_Expression','Stmt_If','Stmt_ElseIf','Stmt_Else','Stmt_Foreach','Stmt_Unset',
            'Expr_Array','ArrayItem','Expr_ArrayDimFetch','Expr_Assign','Expr_BooleanNot','Expr_Empty','Expr_Isset',
            'Expr_FuncCall','Expr_MethodCall','Expr_StaticCall','Expr_New','Expr_Instanceof','Expr_Ternary','Expr_Variable',
            'Expr_ConstFetch','Expr_PreInc','Expr_PostInc','Expr_PreDec','Expr_PostDec','Expr_UnaryMinus','Expr_UnaryPlus',
            'Expr_BinaryOp_BooleanAnd','Expr_BinaryOp_BooleanOr','Expr_BinaryOp_LogicalAnd','Expr_BinaryOp_LogicalOr',
            'Expr_BinaryOp_Concat','Expr_BinaryOp_Equal','Expr_BinaryOp_NotEqual','Expr_BinaryOp_Identical',
            'Expr_BinaryOp_NotIdentical','Expr_BinaryOp_Smaller','Expr_BinaryOp_SmallerOrEqual','Expr_BinaryOp_Greater',
            'Expr_BinaryOp_GreaterOrEqual','Expr_BinaryOp_Plus','Expr_BinaryOp_Minus','Expr_BinaryOp_Mul','Expr_BinaryOp_Div',
            'Expr_BinaryOp_Mod','Expr_BinaryOp_Coalesce','Scalar_Int','Scalar_Float','Scalar_String',
            'Identifier','Name','Name_FullyQualified','Arg',
        ];
        if ($node instanceof \PhpParser\Node\Stmt\InlineHTML && str_contains($node->value, '<?')) self::reject('PHP开放标记');
        if (!in_array($node->getType(), $allowed, true)) self::reject('语法节点 '.$node->getType());
        if (($node instanceof \PhpParser\Node\Arg && ($node->byRef || $node->unpack || $node->name !== null))
            || ($node instanceof \PhpParser\Node\ArrayItem && ($node->byRef || $node->unpack))
            || ($node instanceof \PhpParser\Node\Stmt\Foreach_ && $node->byRef)) self::reject('引用或参数展开');
        if ($node instanceof \PhpParser\Node\Expr\ConstFetch && (!$node->name->isUnqualified() || !in_array(strtolower($node->name->toString()), ['true','false','null'], true))) self::reject('常量');
        if ($node instanceof \PhpParser\Node\Expr\Instanceof_ && (!$node->class instanceof \PhpParser\Node\Name || !in_array(strtolower($node->class->toString()), ['app\\cms\\compat\\collection','app\\cms\\compat\\paginator'], true))) self::reject('类型检查');
        if ($node instanceof \PhpParser\Node\Expr\FuncCall) {
            TemplateCapabilities::validateCall($node);
        } elseif ($node instanceof \PhpParser\Node\Expr\StaticCall) {
            TemplateCapabilities::validateCall($node);
        } elseif ($node instanceof \PhpParser\Node\Expr\New_) {
            if (!$parent instanceof \PhpParser\Node\Expr\Assign || $parent->expr !== $node || !$parent->var instanceof \PhpParser\Node\Expr\Variable || !is_string($parent->var->name) || !$node->class instanceof \PhpParser\Node\Name || strtolower($node->class->getLast()) !== strtolower($parent->var->name) || !preg_match('/^app\\\\cms\\\\compat\\\\template\\\\taglib\\\\eyou\\\\(tag[a-z0-9_]+)$/iD', $node->class->toString(), $m) || !in_array(strtolower($m[1]), self::TAGS, true)) self::reject('对象创建');
        } elseif ($node instanceof \PhpParser\Node\Expr\MethodCall || $node instanceof \PhpParser\Node\Expr\NullsafeMethodCall) {
            if (!$node->name instanceof \PhpParser\Node\Identifier) self::reject('动态方法');
            $method = strtolower($node->name->toString());
            $v = $node->var;
            if ($v instanceof \PhpParser\Node\Expr\Variable && is_string($v->name) && in_array(strtolower($v->name), self::TAGS, true)) {
                $tag = strtolower($v->name);
                if (!in_array($tag, self::TAGS, true) || $method !== 'get'.substr($tag, 3)) self::reject('标签方法');
            } elseif (!in_array($method, ['isempty','slice'], true) || !self::safeCollectionReceiver($v)) self::reject('对象方法');
        } elseif ($node instanceof \PhpParser\Node\Expr\Include_ || $node instanceof \PhpParser\Node\Expr\Eval_ || $node instanceof \PhpParser\Node\Expr\Exit_ || $node instanceof \PhpParser\Node\Expr\ShellExec || $node instanceof \PhpParser\Node\Expr\Closure || $node instanceof \PhpParser\Node\Expr\ArrowFunction || $node instanceof \PhpParser\Node\Expr\StaticPropertyFetch || $node instanceof \PhpParser\Node\Expr\PropertyFetch || $node instanceof \PhpParser\Node\Expr\NullsafePropertyFetch) self::reject('危险语法');
        elseif ($node instanceof \PhpParser\Node\Expr\Variable && (!is_string($node->name) || in_array(strtoupper($node->name), ['THIS','GLOBALS','_SERVER','_GET','_POST','_FILES','_COOKIE','_SESSION','_REQUEST','_ENV'], true))) self::reject('特殊变量');
        elseif ($node instanceof \PhpParser\Node\Expr\Assign && $node->var instanceof \PhpParser\Node\Expr\Variable && is_string($node->var->name) && in_array(strtolower($node->var->name), self::TAGS, true)) {
            if (!$node->expr instanceof \PhpParser\Node\Expr\New_ || !$node->expr->class instanceof \PhpParser\Node\Name || strtolower($node->expr->class->getLast()) !== strtolower($node->var->name)) self::reject('标签对象赋值');
        }
        foreach ($node->getSubNodeNames() as $key) {
            $value = $node->$key;
            foreach (is_array($value) ? $value : [$value] as $child) if ($child instanceof \PhpParser\Node) self::visit($child, $node);
        }
    }
    private static function safeCollectionReceiver(\PhpParser\Node\Expr $receiver): bool
    {
        while ($receiver instanceof \PhpParser\Node\Expr\ArrayDimFetch) {
            if (!$receiver->dim instanceof \PhpParser\Node\Scalar\String_ && !$receiver->dim instanceof \PhpParser\Node\Scalar\Int_) return false;
            $receiver = $receiver->var;
        }
        return $receiver instanceof \PhpParser\Node\Expr\Variable && is_string($receiver->name);
    }
    private static function reject(string $kind): never { throw new \InvalidArgumentException('编译模板包含不允许的'.$kind); }
}
